public final class ConsoleClientChecks {
    private final List<String> report=Collections.synchronizedList(new ArrayList<String>());private int phase,wait=30,age;private boolean done;private volatile boolean ready,failed;private UUID network,green,blue,yellow,rfSensor,heSensor;private long hePower;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private void pass(String s){report.add("PASS: "+s);}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private static WorldServer world(){return (WorldServer)player().worldObj;}
    private void server(Runnable r){ServerWork.enqueue(()->{try{r.run();}catch(Throwable e){failed=true;report.add("FAIL: server :: "+e);IndustrialTechnology.log.error("Console fixture",e);}});}
    private static TileConsole console(int x){return (TileConsole)world().getTileEntity(x,72,24);}
    private static WirelessTestFixtures.Tanks tank(){return (WirelessTestFixtures.Tanks)world().getTileEntity(30,72,24);}
    private UUID stick(int x,int y,int z,int side,WirelessEndpoint.Kind kind,String name){EntityPlayerMP p=player();p.setPosition(x+.5,y,z+2);ItemStack s=new ItemStack(ItemWirelessStick.item(kind));((ItemWirelessStick)s.getItem()).onItemUseFirst(s,p,world(),x,y,z,side,.5F,.5F,.5F);net.minecraftforge.common.util.ForgeDirection d=net.minecraftforge.common.util.ForgeDirection.getOrientation(side);TileRedstoneRelay relay=(TileRedstoneRelay)world().getTileEntity(x+d.offsetX,y+d.offsetY,z+d.offsetZ);check(relay!=null&&relay.endpoint!=null,"real sensor placement");WirelessData.get(world()).devices.get(relay.endpoint).name=name;return relay.endpoint;}
    private static void shot(Minecraft mc,String name){ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    private static void click(GuiConsole g,int id)throws Exception{Field f=GuiScreen.class.getDeclaredField("buttonList");f.setAccessible(true);Method action=GuiConsole.class.getDeclaredMethod("actionPerformed",GuiButton.class);action.setAccessible(true);for(Object o:(List)f.get(g))if(((GuiButton)o).id==id){action.invoke(g,o);return;}throw new AssertionError("missing button "+id);}
    private void open(int x){EntityPlayerMP p=player();p.playerNetServerHandler.setPlayerLocation(x,72,27,180,0);p.openGui(IndustrialTechnology.instance,7,world(),x,72,24);}
    private void setup(){WorldServer w=world();EntityPlayerMP p=player();w.getWorldInfo().incrementTotalWorldTime(24000);w.setWorldTime(6000);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");p.inventory.mainInventory[0]=new ItemStack(ModRegistry.terminal);p.inventory.currentItem=0;network=WirelessAccess.terminal(p,p.getHeldItem(),true);
        w.setBlock(20,72,24,ConsoleRegistry.history,3,3);w.setBlock(22,72,24,ConsoleRegistry.controller,3,3);for(int x:new int[]{20,22}){console(x).owner=p.getUniqueID();console(x).network=network;}
        w.setBlock(30,72,24,WirelessTestFixtures.tanks,0,3);tank().water.setCapacity(4000000);tank().water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,2000000));green=stick(30,72,24,3,WirelessEndpoint.Kind.MONITOR,"Water storage");blue=stick(30,72,24,2,WirelessEndpoint.Kind.AUTOMATION,"Water Blue sensor");w.setBlock(36,72,24,Blocks.iron_block,0,3);yellow=stick(36,72,24,3,WirelessEndpoint.Kind.CONTROL,"Water Auto");
        for(int x:new int[]{40,41}){w.setBlock(x,72,24,ModRegistry.capacitorBank,3,3);TileCapacitorBank b=(TileCapacitorBank)w.getTileEntity(x,72,24);ItemStack s=new ItemStack(ModRegistry.capacitorBank);NBTTagCompound n=new NBTTagCompound();n.setInteger("BankVersion",1);n.setLong("StoredRF",25000000);s.setTagCompound(n);b.restoreItem(s);}rfSensor=stick(40,72,24,3,WirelessEndpoint.Kind.MONITOR,"RF capacitor bank");
        w.setBlock(44,72,24,com.hbm.blocks.ModBlocks.machine_battery,0,3);Object battery=w.getTileEntity(44,72,24);try{hePower=Math.min(123456,((Number)battery.getClass().getMethod("getMaxPower").invoke(battery)).longValue());battery.getClass().getMethod("setPower",long.class).invoke(battery,hePower);}catch(Exception e){throw new RuntimeException(e);}heSensor=stick(44,72,24,3,WirelessEndpoint.Kind.CONTROL,"HBM battery Yellow");
        TileConsole h=console(20);h.channels[0].source=green;h.channels[0].expected="water";h.channels[0].seriesKey="mB:water";for(int i=0;i<=60;i++)h.channels[0].history.add(18000+i*100,1400000+i*10000);h.poll(0,24001);h.channels[1].source=rfSensor;h.channels[1].energy=true;h.channels[1].autoMetric=false;h.channels[2].source=heSensor;h.channels[2].energy=true;h.channels[2].autoMetric=false;
        TileConsole c=console(22);c.channels[0].source=blue;c.channels[0].target=yellow;c.channels[0].low=1800000;c.channels[0].high=2000000;
        p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.playerNetServerHandler.setPlayerLocation(21.5,74,29.5,180,24);p.inventory.currentItem=1;ready=true;
    }
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
        if(failed){finish();return;}
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(26,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("console-client","Disposable console visual QA",s);phase=1;wait=70;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++age>100)throw new AssertionError("join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);TooltipClientChecks.prepare(mc);server(this::setup);phase=2;wait=70;return;}
        if(phase==2){if(!ready){wait=10;return;}check(GL11.glGetError()==0,"world GL error");mc.gameSettings.hideGUI=true;shot(mc,"console-blocks-world.png");mc.gameSettings.hideGUI=false;pass("Both native industrial cases and pixel displays render without missing textures or tile renderers");server(()->open(20));phase=3;wait=30;return;}
        if(phase==3){check(mc.currentScreen instanceof GuiConsole,"history screen missing");GuiConsole g=(GuiConsole)mc.currentScreen;check(g.state.getBoolean("Linked")&&g.state.getCompoundTag("Row").getIntArray("Times").length>100,"history packet");check(g.state.getCompoundTag("Row").getCompoundTag("Reading").getLong("Amount")==2000000,"live reading");shot(mc,"tank-history-fluid.png");check(GL11.glGetError()==0,"graph GL error");pass("Real history GUI shows live fluid, saved samples, net rate and target estimate");server(()->{player().closeScreen();open(22);});phase=4;wait=30;return;}
        if(phase==4){GuiConsole g=(GuiConsole)mc.currentScreen;check(g.state.getBoolean("Controller"),"controller screen");click(g,11);phase=5;wait=65;return;}
        if(phase==5){GuiConsole g=(GuiConsole)mc.currentScreen;check(g.state.getCompoundTag("Row").getBoolean("Enabled")&&g.state.getCompoundTag("Row").getBoolean("Latched"),"enable packet did not drive Yellow");shot(mc,"refinery-controller-on.png");pass("Actual Enable GUI packet applies the 2M/1.8M rule and turns the real Yellow torch ON");server(()->tank().water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,1900000)));phase=6;wait=65;return;}
        if(phase==6){GuiConsole g=(GuiConsole)mc.currentScreen;check(g.state.getCompoundTag("Row").getBoolean("Latched"),"middle band did not hold");server(()->tank().water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,1800000)));phase=7;wait=65;return;}
        if(phase==7){GuiConsole g=(GuiConsole)mc.currentScreen;check(!g.state.getCompoundTag("Row").getBoolean("Latched"),"low did not turn off");shot(mc,"refinery-controller-off.png");pass("Controller holds through the middle band and turns OFF at the lower limit in the actual client/server world");server(()->{player().closeScreen();open(20);ConsoleContainer c=(ConsoleContainer)player().openContainer;c.selected=1;console(20).poll(1,world().getTotalWorldTime());});phase=8;wait=30;return;}
        if(phase==8){GuiConsole g=(GuiConsole)mc.currentScreen;NBTTagCompound r=g.state.getCompoundTag("Row").getCompoundTag("Reading");check(r.getBoolean("Available")&&r.getLong("Amount")==50000000&&r.getString("Unit").equals("RF"),"RF network telemetry");shot(mc,"tank-history-rf.png");pass("History monitor reads the whole 50M RF capacitor network in RF");server(()->{ConsoleContainer c=(ConsoleContainer)player().openContainer;c.selected=2;console(20).poll(2,world().getTotalWorldTime());});phase=9;wait=30;return;}
        if(phase==9){GuiConsole g=(GuiConsole)mc.currentScreen;NBTTagCompound r=g.state.getCompoundTag("Row").getCompoundTag("Reading");check(r.getBoolean("Available")&&r.getLong("Amount")==hePower&&r.getString("Unit").equals("HE"),"HE Yellow telemetry");shot(mc,"tank-history-hbm-he.png");pass("A real Yellow stick reports HBM battery HE in the new monitor without RF conversion");server(()->{player().closeScreen();player().inventory.currentItem=0;player().openGui(IndustrialTechnology.instance,1,world(),0,0,0);TerminalContainer c=(TerminalContainer)player().openContainer;c.tab=1;c.selected=heSensor;});phase=10;wait=30;return;}
        if(phase==10){check(mc.currentScreen instanceof GuiWirelessTerminal,"terminal GUI missing");GuiWirelessTerminal g=(GuiWirelessTerminal)mc.currentScreen;check(g.state.getCompoundTag("Energy").getBoolean("Available")&&g.state.getCompoundTag("Energy").getLong("Amount")==hePower,"Yellow terminal energy missing");shot(mc,"yellow-stick-hbm-energy.png");pass("Existing Yellow controls show actual battery HE alongside their unchanged redstone controls");check(GL11.glGetError()==0,"UI GL error");pass("Console graphs, controller and terminal finish with no OpenGL errors");finish();}
    }catch(Throwable ex){failed=true;report.add("FAIL: client phase "+phase+" :: "+ex);IndustrialTechnology.log.error("Console client",ex);finish();}}
    private void finish(){if(done)return;done=true;try{report.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"console-client-report.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Console client report",e);}Minecraft.getMinecraft().shutdown();}
}
